def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    prev_high_need_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = float(prev['bid'])
            prev_bids.append(bid)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                prev_high_need_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    high_need_prev = max(prev_high_need_bids) if prev_high_need_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days == 1:
        urgency += 0.15
    urgency += 0.2 * scarcity
    if day >= 8:
        urgency += 0.1

    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.92, highest_prev + 1.5)
    elif hp <= 4 or no_water_days == 1:
        target = max(DAILY_SALARY * (0.62 + 0.18 * scarcity), min(highest_prev + 1.0, DAILY_SALARY * 0.9))
    else:
        if highest_prev >= DAILY_SALARY * 1.2:
            target = DAILY_SALARY * (0.28 + 0.08 * scarcity)
        elif highest_prev >= DAILY_SALARY * 0.95:
            target = DAILY_SALARY * (0.38 + 0.12 * scarcity)
        elif highest_prev > 0:
            target = max(DAILY_SALARY * (0.48 + 0.12 * scarcity), highest_prev * 0.82)
        else:
            target = DAILY_SALARY * (0.5 + 0.12 * scarcity)

    if budget < DAILY_SALARY * 2 and urgency < 0.5:
        target *= 0.82
    if budget > DAILY_SALARY * 8 and urgency > 0.35:
        target *= 1.05

    target = min(target, DAILY_SALARY * 1.02)
    bid = min(float(budget), float(target))

    if bid < 0:
        bid = 0.0
    return float(bid)

