    DAILY_SALARY = 90
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not yesterday_bids:
        return min(my_status['budget'], 45.0)

    max_prev = max(yesterday_bids)
    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)

    if max_prev > 80:
        return min(my_status['budget'], 40.0)

    return min(my_status['budget'], max(45.0, max_prev + 2.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive_ids = []
    for agent_id, st in opponents_status.items():
        if st.get('alive', False):
            alive_ids.append(agent_id)

    if not alive_ids:
        # If alone, bid enough to secure water but avoid waste
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.35))

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for agent_id in alive_ids:
        prev = opponents_status[agent_id].get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Compute a pressure estimate
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply regime: in medium scenario supply is between 15 and 25.
    # If supply is closer to WATER_REQ, competition is harsher; bid higher.
    # Use a smooth scaling to avoid mirroring the suicides.
    # Normalize supply to [0,1]
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        s_norm = 0.5
    else:
        s_norm = (supply - float(MIN_SUPPLY)) / denom
    if s_norm < 0.0:
        s_norm = 0.0
    if s_norm > 1.0:
        s_norm = 1.0

    # Base bid: moderate fraction of salary, higher when supply is tight.
    # When supply ~15, bid ~0.70*salary; when supply ~25, bid ~0.45*salary.
    base = DAILY_SALARY * (0.70 - 0.25 * s_norm)

    # If opponents were bidding extremely high yesterday, don't fully chase it.
    # Instead, slightly increase only if my HP is at risk.
    # Threshold tuned to observed max bids (~98) with salary 150.
    extreme_threshold = DAILY_SALARY * 0.70

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # Risk factor: low HP -> bid more
    if hp <= 1.5:
        risk_mult = 0.95
    elif hp <= 3.0:
        risk_mult = 0.80
    elif hp <= 6.0:
        risk_mult = 0.65
    else:
        risk_mult = 0.55

    bid = base * risk_mult

    # If yesterday highest bid was extreme, increase only if I'm weak.
    if prev_bids and highest_prev_bid >= extreme_threshold:
        # If I'm weak, try to secure water; otherwise, hold line.
        if hp <= 3.0:
            bid = max(bid, DAILY_SALARY * 0.60)
        else:
            bid = min(bid, DAILY_SALARY * 0.55)

    # If yesterday average bid was high, small bump to avoid being outbid.
    if prev_bids and avg_prev_bid >= DAILY_SALARY * 0.45:
        bid = max(bid, DAILY_SALARY * (0.48 - 0.05 * s_norm))

    # Ensure bid doesn't exceed budget
    if budget <= 0.0:
        return 0.0

    # Keep some budget for later; don't spend all unless very low HP.
    if hp <= 2.0:
        cap = budget
    else:
        cap = min(budget, DAILY_SALARY * 0.75)

    if cap < 0.0:
        cap = 0.0

    # Final clamp
    if bid > cap:
        bid = cap
    if bid < 0.0:
        bid = 0.0

    return float(bid)
